/**
 * الأصولُ النصّية المشحونة — تُستورد نصّاً فتُحزَم داخل الملفّ التنفيذيّ
 * عند `bun build --compile`. مصدرٌ واحد: الملفّ تحت `assets/` هو النصّ
 * المقروء والمراجَع، وهو نفسه ما يُكتب على قرص المستخدم — لا نسخةَ ثانية
 * في TS تُراجع وحدها ثم تفترق.
 */
declare module "*.ps1" {
  const text: string
  export default text
}
